{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Mithramycin, a large glycosylated aromatic polyketide with multiple sugars and phenolic ketones, showed a peak CSF:plasma ratio of only 0.12 in monkeys and little brain distribution, indicating poor CNS access; this is the closest structural analogue and supports a fail prediction for the similarly glycosylated/phenolic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin, a glycosylated cardiac glycoside, had a very low CSF/plasma ratio (0.01-0.03) in dogs, demonstrating that glycosylated polycyclic natural products with multiple polar sugars do not easily penetrate the BBB; this supports fail.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Vertilmicin, an aminoglycoside bearing multiple amino sugars and hydroxyls, showed the lowest brain concentration among tissues after IV dosing in rats, indicating very low BBB permeation; the query's amino sugar and polyhydroxylated glycoside features align with this poor-penetration phenotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Gentamicin, an aminoglycoside with amino sugars, did not achieve adequate therapeutic CSF levels in humans after systemic administration, supporting the expectation that the query's polar aminosugar glycoside will not confer meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "CMT-3, a lipophilic tetracycline, accumulated in rat brain (4 µg/g) and was labeled permeable, providing a contradictory example that some polyketide/phenolic antibiotics can cross the BBB; however, the query is much more polar and glycosylated, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, polar, glycosylated anthracycline-like molecule with an amino sugar and multiple hydroxyls. The most relevant experimental analogues—mithramycin, digitoxin, vertilmicin, and gentamicin—all show poor BBB/CSF penetration, and their structural features (multiple sugars, phenolic ketones, polar ionizable groups) transfer to the query. Contradictory permeable examples are smaller, more lipophilic, or less glycosylated and do not outweigh the consistent poor-penetration evidence.",
  "evidence_gaps": [
    "No direct brain, CSF, or plasma pharmacokinetic measurement exists for the query molecule itself.",
    "No explicit P-glycoprotein or efflux-transporter data are available for the query.",
    "Morgan similarities to the experimental evidence are modest (<0.27), so structural transfer is approximate."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

